def compute(vars):
    net_income = vars["Net Income"]
    revenue = vars["Revenue"]

    if revenue == 0:
        return None

    net_profit_margin = net_income / revenue
    return {
        "value": net_profit_margin,
        "trace": {
            "Net Income": net_income,
            "Revenue": revenue,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
